firmware:
const int SEG_PINS[7] = {13, 12, 14, 27, 26, 25, 33};  // A B C D E F G
const byte DIGITS[10] = {
  0b1111110,  // 0: A B C D E F
  0b0110000,  // 1: B C
  0b1101101,  // 2: A B D E G
  0b1111001,  // 3: A B C D G
  0b0110011,  // 4: B C F G
  0b1011011,  // 5: A C D F G
  0b1011111,  // 6: A C D E F G
  0b1110000,  // 7: A B C
  0b1111111,  // 8: all
  0b1111011,  // 9: A B C D F G
};
int digit = 0;

void showDigit(int n) {
  byte pattern = DIGITS[n];
  for (int i = 0; i < 7; i++) {
    bool on = pattern & (1 << (6 - i));
    digitalWrite(SEG_PINS[i], on ? HIGH : LOW);
  }
}

void setup() {
  Serial.begin(115200);
  for (int i = 0; i < 7; i++) {
    pinMode(SEG_PINS[i], OUTPUT);
    digitalWrite(SEG_PINS[i], LOW);
  }
}

void loop() {
  showDigit(digit);
  Serial.print("DIGIT=");
  Serial.println(digit);
  digit = (digit + 1) % 10;
  delay(500);
}
